import { readFile, writeFile } from 'node:fs/promises';

const TRANSLATION_MODEL_ID = 'Xenova/opus-mt-en-es';
const MAX_CUES = 2_000;
const MAX_TEXT_CHARACTERS = 200_000;

/**
 * Isolated English-to-Spanish translator used by the subtitle workshop.
 *
 * Input and output paths are generated by the server inside its private job
 * directory. The browser can select only this fixed model and language pair;
 * it never controls model URLs, cache paths, processes, or command arguments.
 */
async function main() {
  const [inputPath, outputPath, cacheDirectory, allowDownloadValue = 'true'] = process.argv.slice(2);
  if (!inputPath || !outputPath || !cacheDirectory) throw new Error('Missing translation worker arguments.');

  const payload = JSON.parse(await readFile(inputPath, 'utf8'));
  if (!Array.isArray(payload?.texts) || payload.texts.length < 1 || payload.texts.length > MAX_CUES) {
    throw new Error('The translation request contains an invalid cue count.');
  }
  const texts = payload.texts.map((value) => String(value || '').replace(/\s+/g, ' ').trim());
  if (texts.some((value) => !value)) throw new Error('Every subtitle cue must contain text.');
  if (texts.reduce((total, value) => total + value.length, 0) > MAX_TEXT_CHARACTERS) {
    throw new Error('The translation request is too large.');
  }

  const { pipeline, env } = await import('@huggingface/transformers');
  env.cacheDir = cacheDirectory;
  env.allowRemoteModels = /^true$/i.test(allowDownloadValue);
  env.allowLocalModels = true;
  env.remoteHost = 'https://huggingface.co';
  const translator = await pipeline('translation', TRANSLATION_MODEL_ID, {
    device: 'cpu',
    dtype: 'q8'
  });

  const translated = [];
  for (let start = 0; start < texts.length; start += 8) {
    const batch = texts.slice(start, start + 8);
    const result = await translator(batch, { max_new_tokens: 256, num_beams: 4 });
    const records = Array.isArray(result) ? result : [result];
    if (records.length !== batch.length) throw new Error('The translation model returned an unexpected cue count.');
    for (const entry of records) {
      const record = Array.isArray(entry) ? entry[0] : entry;
      const value = String(record?.translation_text || record?.generated_text || '')
        .replace(/[\u0000-\u001f]+/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
      if (!value) throw new Error('The translation model returned an empty cue.');
      translated.push(value);
    }
    process.stdout.write(`${JSON.stringify({ type: 'progress', completed: translated.length, total: texts.length })}\n`);
  }

  await writeFile(outputPath, JSON.stringify({ texts: translated }), 'utf8');
}

main().catch((error) => {
  process.stderr.write(`${error?.stack || error}\n`);
  process.exitCode = 1;
});
